<script>
 import {layout,inspectorMax,saveLayout} from '../layout.svelte';import ResizeHandle from './ResizeHandle.svelte';
 import {Sun,Contrast,Droplets,Thermometer,RotateCcw,RotateCw,FlipHorizontal,FlipVertical,Eye,EyeOff,Lock,Undo2,Redo2,Check,Clock,ArrowUpRight,X} from 'lucide-svelte';
 import {studio,asset,change,remember,undo,redo,restoreVersion,run,save,notify} from '../studio.svelte';import {initialEdit,bytes} from '../api';import Histogram from './Histogram.svelte';
 import {slide} from 'svelte/transition';import {cubicOut} from 'svelte/easing';
 let {onclose}=$props();const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 let numberCheckpoint='';
 function exactNumber(key,e){if(e.currentTarget.value===''||!e.currentTarget.validity.valid)return;if(numberCheckpoint!==key){remember();numberCheckpoint=key;}change({[key]:Number(e.currentTarget.value)},false);}
 const controls=[{key:'exposure',name:'Exposure',icon:Sun,min:-3,max:3,step:.05},{key:'contrast',name:'Contrast',icon:Contrast,min:0,max:3,step:.01},{key:'saturation',name:'Saturation',icon:Droplets,min:0,max:3,step:.01},{key:'temperature',name:'Temperature',icon:Thermometer,min:-1,max:1,step:.01}];
 const looks=[['Original',{}],['Runner',{contrast:1.2,saturation:.75,temperature:-.1}],['Concrete',{contrast:1.14,saturation:0}],['Signal',{contrast:1.14,saturation:1.3}],['Dawn',{exposure:.2,temperature:.25}]];
 function crop(ratio){const a=asset();if(!a)return;if(!ratio){change({crop:null});return;}const r=a.width/a.height;if(r>ratio){const w=ratio/r;change({crop:[(1-w)/2,0,w,1]});}else{const h=r/ratio;change({crop:[0,(1-h)/2,1,h]});}}
</script>
<aside id="editor-inspector" aria-label="Image inspector" class="inspector" style:width={`${Math.min(layout.inspectorWidth,inspectorMax())}px`} inert={!!studio.busy||!studio.inspector} transition:slide={{axis:'x',duration:reducedMotion?0:180,easing:cubicOut}}>
 <ResizeHandle axis="width" bind:value={layout.inspectorWidth} min={220} max={inspectorMax()} label="Inspector width" onfinish={saveLayout} reset={()=>layout.inspectorWidth=280}/>
 <div class="inspector-title"><h2>{studio.inspectorTab==='history'?'History':studio.inspectorTab==='layers'?'Layers':studio.tool==='crop'?'Crop':studio.tool==='transform'?'Transform':'Adjustments'}</h2><div class="inspector-title-actions"><button aria-label="Reset edits" title="Reset edits" disabled={!asset()} onclick={()=>change({...initialEdit})}><RotateCcw size={15}/></button><button aria-label="Close inspector" title="Close inspector" onclick={onclose}><X size={17}/></button></div></div>
 <div class="inspector-tabs"><button class:active={studio.inspectorTab==='adjust'} onclick={()=>studio.inspectorTab='adjust'}>Adjust</button><button class:active={studio.inspectorTab==='layers'} onclick={()=>studio.inspectorTab='layers'}>Layers</button><button class:active={studio.inspectorTab==='history'} onclick={()=>studio.inspectorTab='history'}>History</button></div>
 <div class="inspector-scroll">
 {#if asset()}
 {#if studio.inspectorTab==='adjust'}
 {#if studio.tool==='crop'}<section><h3>Aspect ratio</h3><div class="ratio-grid">{#each [['Original',0],['1:1',1],['4:5',.8],['16:9',16/9],['3:2',1.5],['2:3',2/3]] as [label,ratio]}<button onclick={()=>crop(ratio)}>{label}</button>{/each}</div><p class="hint">Crop on the canvas for a custom frame.</p>{#if studio.draft.crop}<div class="field-grid">{#each ['X','Y','Width','Height'] as label,i}<label>{label}<input aria-label={`Crop ${label}`} type="number" step=".01" min="0" max="1" value={studio.draft.crop[i]} onchange={e=>{const c=[...studio.draft.crop];c[i]=Number(e.target.value);if(c[2]>0&&c[3]>0&&c[0]+c[2]<=1&&c[1]+c[3]<=1)change({crop:c});}}/></label>{/each}</div>{/if}</section>
 {:else if studio.tool==='transform'}<section><h3>Orientation</h3><div class="transform-grid"><button onclick={()=>change({rotation:(studio.draft.rotation+270)%360})}><RotateCcw size={19}/>−90°</button><button onclick={()=>change({rotation:(studio.draft.rotation+90)%360})}><RotateCw size={19}/>+90°</button><button class:active={studio.draft.flipH} onclick={()=>change({flipH:!studio.draft.flipH})}><FlipHorizontal size={19}/>Horizontal</button><button class:active={studio.draft.flipV} onclick={()=>change({flipV:!studio.draft.flipV})}><FlipVertical size={19}/>Vertical</button></div></section>
 {:else}<section class="looks-section"><h3>Looks</h3><div class="looks">{#each looks as [name,patch],i}<button onclick={()=>change({...initialEdit,crop:studio.draft.crop,rotation:studio.draft.rotation,flipH:studio.draft.flipH,flipV:studio.draft.flipV,...patch})}><img src={studio.thumbs[studio.aid]} alt="" style:filter={i===2?'grayscale(1)':i===3?'saturate(1.5)':i===4?'sepia(.4)':i===1?'contrast(1.3)':'none'}/><span>{name}</span></button>{/each}</div></section>{/if}
 <section class="sliders-section"><h3>Light & color</h3>{#each controls as c}<div class="adjustment"><label for={c.key}><c.icon size={14}/>{c.name}</label><input class="numeric" aria-label={`${c.name} value`} type="number" step={c.step} min={c.min} max={c.max} value={Number(studio.draft[c.key].toFixed(2))} onfocus={()=>numberCheckpoint=''} onblur={()=>numberCheckpoint=''} oninput={e=>exactNumber(c.key,e)}/><input id={c.key} aria-label={c.name} type="range" min={c.min} max={c.max} step={c.step} value={studio.draft[c.key]} onpointerdown={remember} onkeydown={e=>{if(e.key.startsWith('Arrow'))remember();}} oninput={e=>change({[c.key]:Number(e.target.value)},false)}/></div>{/each}</section>
 {:else if studio.inspectorTab==='layers'}<section class="layers"><h3>Layers</h3><div class="layer"><button aria-label="Toggle adjustment layer" onclick={()=>change({adjustmentEnabled:!studio.draft.adjustmentEnabled})}>{#if studio.draft.adjustmentEnabled}<Eye size={16}/>{:else}<EyeOff size={16}/>{/if}</button><span>Color adjustments</span></div><label class="opacity-label">Opacity <span>{Math.round(studio.draft.adjustmentOpacity*100)}%</span><input aria-label="Adjustment opacity" type="range" min="0" max="1" step=".01" value={studio.draft.adjustmentOpacity} onpointerdown={remember} oninput={e=>change({adjustmentOpacity:Number(e.target.value)},false)}/></label><div class="layer original"><Lock size={15}/><img src={studio.thumbs[studio.aid]} alt=""/><span>Original</span></div></section>
 {:else}<section class="versions"><div class="section-row"><h3>Saved versions</h3><button class="text-button" onclick={()=>run('Saving',async()=>{await save([studio.aid]);notify('Version saved');})}>Save</button></div>{#each [...asset().versions].reverse() as v}<div class="version"><Clock size={14}/><div><b>{v.kind==='generated'?'Generated':v.kind==='local'?'Local process':'Edit'}</b><small>{new Date(v.createdAt*1000).toLocaleString()}</small></div><button title="Restore version" aria-label={`Restore ${v.id}`} onclick={()=>restoreVersion(v.id)}><RotateCcw size={14}/></button>{#if v.kind==='generated'||v.kind==='local'}<button title="Review version" aria-label={`Review ${v.id}`} onclick={()=>studio.modal={type:'review',version:v}}><ArrowUpRight size={14}/></button>{/if}</div>{/each}{#if !asset().versions.length}<p class="hint">No saved versions</p>{/if}<button class="line-button full" onclick={()=>restoreVersion(null)}>Restore original</button></section>{/if}
 <section class="histogram"><div class="section-row"><h3>Histogram</h3><span>RGB</span></div><Histogram src={studio.preview}/><div class="histogram-scale"><span>0</span><span>128</span><span>255</span></div></section><section class="asset-details"><div><span>Dimensions</span><b>{asset().width} × {asset().height}</b></div><div><span>Source</span><b>{bytes(asset().bytes)}</b></div><div><span>Versions</span><b>{asset().versions.length}</b></div></section>
 {:else}<div class="empty small">Select an image</div>{/if}
 </div><div class="inspector-bottom"><button onclick={()=>studio.compare=!studio.compare} disabled={!asset()}><Eye size={15}/>Before / After</button><div><button aria-label="Undo" disabled={!studio.history[studio.aid]?.length} onclick={undo}><Undo2 size={17}/></button><button aria-label="Redo" disabled={!studio.redo[studio.aid]?.length} onclick={redo}><Redo2 size={17}/></button></div></div>
</aside>
